-- ============================================================================
-- GENERATED by scripts/payments/gen-probe-import-parity.mjs — edit that, not this.
--
-- Service Payments — does the Import screen's PREVIEW tell the truth?
--
-- One scenario, two judges. The screen's own diff functions (importPlan.js)
-- predicted every count below when this file was generated; this probe plays
-- the same scenario through the REAL import RPCs and fails on any difference.
-- It also checks the invariants no count can hide: no payment stored twice,
-- a hand-keyed amount never touched, a cancelled bill never left holding money.
--
-- WRITES NOTHING: the last statement raises "PROBE COMPLETE", rolling back.
-- Run through MCP apply_migration (execute_sql is read-only) or the SQL editor.
-- Staging first. It creates only ZZPROBE rows and touches no existing row.
-- ============================================================================

CREATE OR REPLACE FUNCTION pg_temp.zz_fail(msg text) RETURNS void LANGUAGE plpgsql AS $f$
BEGIN
  PERFORM set_config('zz.fails', current_setting('zz.fails', true) || ' | ' || msg, true);
END $f$;
CREATE OR REPLACE FUNCTION pg_temp.zz_check(label text, got int, want int) RETURNS void LANGUAGE plpgsql AS $f$
BEGIN
  PERFORM set_config('zz.checks', (coalesce(nullif(current_setting('zz.checks', true), ''), '0')::int + 1)::text, true);
  IF got IS DISTINCT FROM want THEN
    PERFORM pg_temp.zz_fail(label || ': server ' || coalesce(got::text, 'null') || ', preview ' || want);
  END IF;
END $f$;

DO $probe$
DECLARE
  v_entity uuid;
  v_actor  uuid;
  v_res    jsonb;
  v_rcpt   uuid;
  v_c      uuid;
  v_d      uuid;
  v_n      bigint;
  v_fails  text;
BEGIN
  PERFORM set_config('zz.fails', '', true);
  PERFORM set_config('zz.checks', '0', true);
  SELECT id INTO v_entity FROM public.entities WHERE code = 'PTB';
  SELECT id INTO v_actor FROM public.users WHERE permission_level = 'admin' LIMIT 1;
  IF v_entity IS NULL OR v_actor IS NULL THEN RAISE EXCEPTION 'need the PTB entity and an admin'; END IF;
  IF EXISTS (SELECT 1 FROM public.service_invoices WHERE invoice_number LIKE 'ZZPROBE-%')
  OR EXISTS (SELECT 1 FROM public.payment_receipts WHERE payer_name = 'ZZ PROBE PAYER') THEN
    RAISE EXCEPTION 'ZZPROBE rows already exist — refusing to run over them';
  END IF;

  -- ══ BILLS ═════════════════════════════════════════════════════════════
  
  BEGIN
    v_res := public.payments_import_invoices(v_entity, '[{"invoice_number":"ZZPROBE-A","sap_customer_code":"ZZC1","customer_name":"ZZ PROBE 1","invoice_kind":"counter_sale","invoice_date":"2026-09-20","payment_terms":"cash","net_paise":100000,"tax_paise":0,"total_paise":100000,"status":"active","cancelled_flag":null},{"invoice_number":"ZZPROBE-B","sap_customer_code":"ZZC1","customer_name":"ZZ PROBE 1","invoice_kind":"counter_sale","invoice_date":"2026-09-20","payment_terms":"cash","net_paise":200000,"tax_paise":0,"total_paise":200000,"status":"active","cancelled_flag":null},{"invoice_number":"ZZPROBE-C","sap_customer_code":"ZZC2","customer_name":"ZZ PROBE 2","invoice_kind":"counter_sale","invoice_date":"2026-09-20","payment_terms":"cash","net_paise":300000,"tax_paise":0,"total_paise":300000,"status":"active","cancelled_flag":null},{"invoice_number":"ZZPROBE-D","sap_customer_code":"ZZC2","customer_name":"ZZ PROBE 2","invoice_kind":"counter_sale","invoice_date":"2026-09-20","payment_terms":"cash","net_paise":400000,"tax_paise":0,"total_paise":400000,"status":"active","cancelled_flag":null},{"invoice_number":"ZZPROBE-E","sap_customer_code":"ZZC3","customer_name":"ZZ PROBE 3","invoice_kind":"counter_sale","invoice_date":"2026-09-20","payment_terms":"cash","net_paise":500000,"tax_paise":0,"total_paise":500000,"status":"active","cancelled_flag":null}]'::jsonb, '{"source":"probe","parser_version":"probe"}'::jsonb, v_actor);
  EXCEPTION WHEN others THEN
    v_res := jsonb_build_object('error', SQLERRM);
    PERFORM pg_temp.zz_fail('bills #1 THREW: ' || SQLERRM);
  END;
  
  PERFORM pg_temp.zz_check('bills #1 new', (v_res->>'new')::int, 5);
  PERFORM pg_temp.zz_check('bills #1 amended', (v_res->>'amended')::int, 0);
  PERFORM pg_temp.zz_check('bills #1 unchanged', (v_res->>'unchanged')::int, 0);
  PERFORM pg_temp.zz_check('bills #1 conflicts', jsonb_array_length(v_res->'conflicts'), 0);

  -- Match money: all of C, 1,500 of D (paise 300000 / 150000).
  INSERT INTO public.payment_receipts (entity_id, mode, source, amount_paise, received_at, payer_name, classification)
  VALUES (v_entity, 'cash', 'manual', 450000, now(), 'ZZ PROBE PAYER', 'service')
  RETURNING id INTO v_rcpt;
  SELECT id INTO v_c FROM public.service_invoices WHERE entity_id = v_entity AND invoice_number = 'ZZPROBE-C';
  SELECT id INTO v_d FROM public.service_invoices WHERE entity_id = v_entity AND invoice_number = 'ZZPROBE-D';
  PERFORM public.payments_allocate(v_entity, v_rcpt,
    jsonb_build_array(jsonb_build_object('invoice_id', v_c, 'amount_paise', 300000),
                      jsonb_build_object('invoice_id', v_d, 'amount_paise', 150000)),
    v_actor, NULL, 'probe');

  
  BEGIN
    v_res := public.payments_import_invoices(v_entity, '[{"invoice_number":"ZZPROBE-A","sap_customer_code":"ZZC1","customer_name":"ZZ PROBE 1","invoice_kind":"counter_sale","invoice_date":"2026-09-20","payment_terms":"cash","net_paise":100000,"tax_paise":0,"total_paise":100000,"status":"active","cancelled_flag":null},{"invoice_number":"ZZPROBE-B","sap_customer_code":"ZZC1","customer_name":"ZZ PROBE 1","invoice_kind":"counter_sale","invoice_date":"2026-09-20","payment_terms":"cash","net_paise":250000,"tax_paise":0,"total_paise":250000,"status":"active","cancelled_flag":null},{"invoice_number":"ZZPROBE-C","sap_customer_code":"ZZC2","customer_name":"ZZ PROBE 2","invoice_kind":"counter_sale","invoice_date":"2026-09-20","payment_terms":"cash","net_paise":300000,"tax_paise":0,"total_paise":300000,"status":"cancelled","cancelled_flag":"X"},{"invoice_number":"ZZPROBE-D","sap_customer_code":"ZZC2","customer_name":"ZZ PROBE 2","invoice_kind":"counter_sale","invoice_date":"2026-09-20","payment_terms":"cash","net_paise":100000,"tax_paise":0,"total_paise":100000,"status":"active","cancelled_flag":null},{"invoice_number":"ZZPROBE-E","sap_customer_code":"ZZC4","customer_name":"ZZ PROBE 4","invoice_kind":"counter_sale","invoice_date":"2026-09-20","payment_terms":"cash","net_paise":500000,"tax_paise":0,"total_paise":500000,"status":"active","cancelled_flag":null},{"invoice_number":"ZZPROBE-F","sap_customer_code":"ZZC1","customer_name":"ZZ PROBE 1","invoice_kind":"counter_sale","invoice_date":"2026-09-20","payment_terms":"cash","net_paise":700000,"tax_paise":0,"total_paise":700000,"status":"active","cancelled_flag":null}]'::jsonb, '{"source":"probe","parser_version":"probe"}'::jsonb, v_actor);
  EXCEPTION WHEN others THEN
    v_res := jsonb_build_object('error', SQLERRM);
    PERFORM pg_temp.zz_fail('bills #2 THREW: ' || SQLERRM);
  END;
  
  PERFORM pg_temp.zz_check('bills #2 new', (v_res->>'new')::int, 1);
  PERFORM pg_temp.zz_check('bills #2 amended', (v_res->>'amended')::int, 1);
  PERFORM pg_temp.zz_check('bills #2 unchanged', (v_res->>'unchanged')::int, 1);
  PERFORM pg_temp.zz_check('bills #2 conflicts', jsonb_array_length(v_res->'conflicts'), 3);

  -- Invariant: a bill with money matched to it is never left cancelled.
  SELECT count(*) INTO v_n FROM public.service_invoices
   WHERE entity_id = v_entity AND invoice_number LIKE 'ZZPROBE-%'
     AND status <> 'active' AND allocated_paise > 0;
  PERFORM pg_temp.zz_check('bills: none left non-active while holding money', v_n::int, 0);

  -- ══ PAYMENTS ══════════════════════════════════════════════════════════
  -- Hand-keyed first, the way a parser outage would leave them.
  PERFORM public.payments_manual_receipt(v_entity, jsonb_build_object(
    'mode','upi','amount_paise',11000,'external_txn_id','990000000001',
    'normalized_utr','990000000001','payer_name','ZZ PROBE PAYER',
    'received_at','2026-09-20T05:00:00Z'), v_actor);
  PERFORM public.payments_manual_receipt(v_entity, jsonb_build_object(
    'mode','upi','amount_paise',22000,'external_txn_id','ZZPROBE-GPAY-1',
    'normalized_utr',NULL,'payer_name','ZZ PROBE PAYER',
    'received_at','2026-09-20T05:00:00Z'), v_actor);
  PERFORM public.payments_manual_receipt(v_entity, jsonb_build_object(
    'mode','upi','amount_paise',66000,'external_txn_id','ZZPROBE-OTHER',
    'normalized_utr','990000000009','payer_name','ZZ PROBE PAYER',
    'received_at','2026-09-20T05:00:00Z'), v_actor);
  PERFORM public.payments_manual_receipt(v_entity, jsonb_build_object(
    'mode','upi','amount_paise',88000,'external_txn_id','700000000011',
    'normalized_utr',NULL,'payer_name','ZZ PROBE PAYER',
    'received_at','2026-09-20T05:00:00Z'), v_actor);
  PERFORM public.payments_manual_receipt(v_entity, jsonb_build_object(
    'mode','upi','amount_paise',12300,'external_txn_id','700000000012',
    'normalized_utr',NULL,'payer_name','ZZ PROBE PAYER',
    'received_at','2026-09-20T05:00:00Z'), v_actor);
  
  BEGIN
    v_res := public.payments_import_receipts(v_entity, '[{"source":"bharatpe","mode":"upi","external_txn_id":"990000000003","normalized_utr":"990000000003","amount_paise":44000,"gross_paise":44000,"fee_paise":0,"received_at":"2026-09-20T05:00:00Z","payer_name":"ZZ PROBE PAYER","payer_remark":null}]'::jsonb, '{"source":"probe","parser_version":"probe"}'::jsonb, v_actor);
  EXCEPTION WHEN others THEN
    v_res := jsonb_build_object('error', SQLERRM);
    PERFORM pg_temp.zz_fail('payments setup THREW: ' || SQLERRM);
  END;

  
  BEGIN
    v_res := public.payments_import_receipts(v_entity, '[{"source":"bharatpe","mode":"upi","external_txn_id":"990000000001","normalized_utr":"990000000001","amount_paise":11000,"gross_paise":11000,"fee_paise":0,"received_at":"2026-09-20T05:00:00Z","payer_name":"ZZ PROBE PAYER","payer_remark":null},{"source":"bharatpe","mode":"upi","external_txn_id":"990000000003","normalized_utr":"990000000003","amount_paise":44000,"gross_paise":44000,"fee_paise":0,"received_at":"2026-09-20T05:00:00Z","payer_name":"ZZ PROBE PAYER","payer_remark":null},{"source":"bharatpe","mode":"upi","external_txn_id":"990000000004","normalized_utr":"990000000004","amount_paise":55000,"gross_paise":55000,"fee_paise":0,"received_at":"2026-09-20T05:00:00Z","payer_name":"ZZ PROBE PAYER","payer_remark":null},{"source":"bharatpe","mode":"upi","external_txn_id":"990000000009","normalized_utr":"990000000009","amount_paise":66000,"gross_paise":66000,"fee_paise":0,"received_at":"2026-09-20T05:00:00Z","payer_name":"ZZ PROBE PAYER","payer_remark":null}]'::jsonb, '{"source":"probe","parser_version":"probe"}'::jsonb, v_actor);
  EXCEPTION WHEN others THEN
    v_res := jsonb_build_object('error', SQLERRM);
    PERFORM pg_temp.zz_fail('BharatPe #1 THREW: ' || SQLERRM);
  END;
  
  PERFORM pg_temp.zz_check('BharatPe #1 new', (v_res->>'new')::int, 1);
  PERFORM pg_temp.zz_check('BharatPe #1 already present', (v_res->>'already_present')::int, 1);
  PERFORM pg_temp.zz_check('BharatPe #1 linked to hand entry', (v_res->>'already_present_manual')::int, 2);
  PERFORM pg_temp.zz_check('BharatPe #1 held', coalesce(jsonb_array_length(v_res->'held'), 0), 0);
  
  BEGIN
    v_res := public.payments_import_receipts(v_entity, '[{"source":"gpay","mode":"upi","external_txn_id":"ZZPROBE-GPAY-1","normalized_utr":null,"amount_paise":22000,"gross_paise":22000,"fee_paise":0,"received_at":"2026-09-20T05:00:00Z","payer_name":"ZZ PROBE PAYER","payer_remark":"ZZ note"},{"source":"gpay","mode":"upi","external_txn_id":"ZZPROBE-GPAY-2","normalized_utr":null,"amount_paise":77000,"gross_paise":77000,"fee_paise":0,"received_at":"2026-09-20T05:00:00Z","payer_name":"ZZ PROBE PAYER","payer_remark":"ZZ note"}]'::jsonb, '{"source":"probe","parser_version":"probe"}'::jsonb, v_actor);
  EXCEPTION WHEN others THEN
    v_res := jsonb_build_object('error', SQLERRM);
    PERFORM pg_temp.zz_fail('Google Pay #1 THREW: ' || SQLERRM);
  END;
  
  PERFORM pg_temp.zz_check('Google Pay #1 new', (v_res->>'new')::int, 1);
  PERFORM pg_temp.zz_check('Google Pay #1 already present', (v_res->>'already_present')::int, 0);
  PERFORM pg_temp.zz_check('Google Pay #1 linked to hand entry', (v_res->>'already_present_manual')::int, 1);
  PERFORM pg_temp.zz_check('Google Pay #1 held', coalesce(jsonb_array_length(v_res->'held'), 0), 0);
  
  BEGIN
    v_res := public.payments_import_receipts(v_entity, '[{"source":"bharatpe","mode":"upi","external_txn_id":"990000000001","normalized_utr":"990000000001","amount_paise":11000,"gross_paise":11000,"fee_paise":0,"received_at":"2026-09-20T05:00:00Z","payer_name":"ZZ PROBE PAYER","payer_remark":null},{"source":"bharatpe","mode":"upi","external_txn_id":"990000000003","normalized_utr":"990000000003","amount_paise":44000,"gross_paise":44000,"fee_paise":0,"received_at":"2026-09-20T05:00:00Z","payer_name":"ZZ PROBE PAYER","payer_remark":null},{"source":"bharatpe","mode":"upi","external_txn_id":"990000000004","normalized_utr":"990000000004","amount_paise":55000,"gross_paise":55000,"fee_paise":0,"received_at":"2026-09-20T05:00:00Z","payer_name":"ZZ PROBE PAYER","payer_remark":null},{"source":"bharatpe","mode":"upi","external_txn_id":"990000000009","normalized_utr":"990000000009","amount_paise":66000,"gross_paise":66000,"fee_paise":0,"received_at":"2026-09-20T05:00:00Z","payer_name":"ZZ PROBE PAYER","payer_remark":null}]'::jsonb, '{"source":"probe","parser_version":"probe"}'::jsonb, v_actor);
  EXCEPTION WHEN others THEN
    v_res := jsonb_build_object('error', SQLERRM);
    PERFORM pg_temp.zz_fail('BharatPe again THREW: ' || SQLERRM);
  END;
  
  PERFORM pg_temp.zz_check('BharatPe again new', (v_res->>'new')::int, 0);
  PERFORM pg_temp.zz_check('BharatPe again already present', (v_res->>'already_present')::int, 4);
  PERFORM pg_temp.zz_check('BharatPe again linked to hand entry', (v_res->>'already_present_manual')::int, 0);
  PERFORM pg_temp.zz_check('BharatPe again held', coalesce(jsonb_array_length(v_res->'held'), 0), 0);
  
  BEGIN
    v_res := public.payments_import_receipts(v_entity, '[{"source":"hdfc","mode":"upi","external_txn_id":"ZZMINT00000000000001","normalized_utr":"700000000011","amount_paise":88000,"gross_paise":88000,"fee_paise":0,"received_at":"2026-09-20T05:00:00Z","payer_name":"ZZ PROBE PAYER","payer_remark":null,"qr_ref":"KTR510/82388473"},{"source":"hdfc","mode":"upi","external_txn_id":"ZZMINT00000000000002","normalized_utr":"700000000012","amount_paise":12000,"gross_paise":12000,"fee_paise":0,"received_at":"2026-09-20T05:00:00Z","payer_name":"ZZ PROBE PAYER","payer_remark":null,"qr_ref":"KTR510/82388473"},{"source":"hdfc","mode":"upi","external_txn_id":"ZZMINT00000000000003","normalized_utr":"700000000013","amount_paise":45600,"gross_paise":45600,"fee_paise":0,"received_at":"2026-09-20T05:00:00Z","payer_name":"ZZ PROBE PAYER","payer_remark":null,"qr_ref":"KTR510/82388473"}]'::jsonb, '{"source":"probe","parser_version":"probe"}'::jsonb, v_actor);
  EXCEPTION WHEN others THEN
    v_res := jsonb_build_object('error', SQLERRM);
    PERFORM pg_temp.zz_fail('HDFC #1 THREW: ' || SQLERRM);
  END;
  
  PERFORM pg_temp.zz_check('HDFC #1 new', (v_res->>'new')::int, 1);
  PERFORM pg_temp.zz_check('HDFC #1 already present', (v_res->>'already_present')::int, 0);
  PERFORM pg_temp.zz_check('HDFC #1 linked to hand entry', (v_res->>'already_present_manual')::int, 1);
  PERFORM pg_temp.zz_check('HDFC #1 held', coalesce(jsonb_array_length(v_res->'held'), 0), 1);
  
  BEGIN
    v_res := public.payments_import_receipts(v_entity, '[{"source":"hdfc","mode":"upi","external_txn_id":"ZZMINT00000000000001","normalized_utr":"700000000011","amount_paise":88000,"gross_paise":88000,"fee_paise":0,"received_at":"2026-09-20T05:00:00Z","payer_name":"ZZ PROBE PAYER","payer_remark":null,"qr_ref":"KTR510/82388473"},{"source":"hdfc","mode":"upi","external_txn_id":"ZZMINT00000000000002","normalized_utr":"700000000012","amount_paise":12000,"gross_paise":12000,"fee_paise":0,"received_at":"2026-09-20T05:00:00Z","payer_name":"ZZ PROBE PAYER","payer_remark":null,"qr_ref":"KTR510/82388473"},{"source":"hdfc","mode":"upi","external_txn_id":"ZZMINT00000000000003","normalized_utr":"700000000013","amount_paise":45600,"gross_paise":45600,"fee_paise":0,"received_at":"2026-09-20T05:00:00Z","payer_name":"ZZ PROBE PAYER","payer_remark":null,"qr_ref":"KTR510/82388473"}]'::jsonb, '{"source":"probe","parser_version":"probe"}'::jsonb, v_actor);
  EXCEPTION WHEN others THEN
    v_res := jsonb_build_object('error', SQLERRM);
    PERFORM pg_temp.zz_fail('HDFC again THREW: ' || SQLERRM);
  END;
  
  PERFORM pg_temp.zz_check('HDFC again new', (v_res->>'new')::int, 0);
  PERFORM pg_temp.zz_check('HDFC again already present', (v_res->>'already_present')::int, 2);
  PERFORM pg_temp.zz_check('HDFC again linked to hand entry', (v_res->>'already_present_manual')::int, 0);
  PERFORM pg_temp.zz_check('HDFC again held', coalesce(jsonb_array_length(v_res->'held'), 0), 1);

  -- Invariants no count can hide.
  SELECT count(*) INTO v_n FROM (
    SELECT external_txn_id FROM public.payment_receipts
     WHERE entity_id = v_entity AND status = 'active' AND payer_name = 'ZZ PROBE PAYER'
       AND external_txn_id IS NOT NULL
     GROUP BY external_txn_id HAVING count(*) > 1) d;
  PERFORM pg_temp.zz_check('payments: no transaction id stored twice', v_n::int, 0);
  SELECT count(*) INTO v_n FROM (
    SELECT normalized_utr FROM public.payment_receipts
     WHERE entity_id = v_entity AND status = 'active' AND payer_name = 'ZZ PROBE PAYER'
       AND normalized_utr IS NOT NULL
     GROUP BY normalized_utr HAVING count(*) > 1) d;
  PERFORM pg_temp.zz_check('payments: no UTR stored twice', v_n::int, 0);
  SELECT amount_paise INTO v_n FROM public.payment_receipts
   WHERE entity_id = v_entity AND source = 'manual' AND external_txn_id = '990000000001';
  PERFORM pg_temp.zz_check('payments: hand-keyed M1 amount untouched', v_n::int, 11000);
  SELECT amount_paise INTO v_n FROM public.payment_receipts
   WHERE entity_id = v_entity AND source = 'manual' AND external_txn_id = 'ZZPROBE-GPAY-1';
  PERFORM pg_temp.zz_check('payments: hand-keyed M2 amount untouched', v_n::int, 22000);
  SELECT amount_paise INTO v_n FROM public.payment_receipts
   WHERE entity_id = v_entity AND source = 'manual' AND external_txn_id = 'ZZPROBE-OTHER';
  PERFORM pg_temp.zz_check('payments: hand-keyed M3 amount untouched', v_n::int, 66000);
  SELECT amount_paise INTO v_n FROM public.payment_receipts
   WHERE entity_id = v_entity AND source = 'manual' AND external_txn_id = '700000000011';
  PERFORM pg_temp.zz_check('payments: hand-keyed M4 amount untouched', v_n::int, 88000);
  SELECT amount_paise INTO v_n FROM public.payment_receipts
   WHERE entity_id = v_entity AND source = 'manual' AND external_txn_id = '700000000012';
  PERFORM pg_temp.zz_check('payments: hand-keyed M5 amount untouched', v_n::int, 12300);
  SELECT count(*) INTO v_n FROM public.payment_receipts
   WHERE entity_id = v_entity AND source = 'manual' AND payer_name = 'ZZ PROBE PAYER'
     AND mode = 'upi' AND import_batch_id IS NOT NULL;
  PERFORM pg_temp.zz_check('payments: exactly the hand entries the preview linked (M1, M2, M3, M4) are linked to a file', v_n::int, 4);
  SELECT count(*) INTO v_n FROM public.payment_receipts
   WHERE entity_id = v_entity AND source = 'manual' AND external_txn_id = '700000000011' AND qr_ref = 'KTR510/82388473';
  PERFORM pg_temp.zz_check('payments: the linked HDFC hand entry learned which QR it came on', v_n::int, 1);
  SELECT count(*) INTO v_n FROM public.payment_receipts
   WHERE entity_id = v_entity AND (normalized_utr = '700000000012' OR external_txn_id = 'ZZMINT00000000000002');
  PERFORM pg_temp.zz_check('payments: the wrong-amount entry was neither linked nor copied (only the hand entry exists)', v_n::int, 0);
  SELECT count(*) INTO v_n FROM public.payment_receipts
   WHERE entity_id = v_entity AND external_txn_id = '700000000012' AND import_batch_id IS NULL;
  PERFORM pg_temp.zz_check('payments: ...and the hand entry itself is untouched', v_n::int, 1);
  SELECT count(*) INTO v_n FROM public.payment_receipts
   WHERE entity_id = v_entity AND source = 'hdfc' AND qr_ref = 'KTR510/82388473';
  PERFORM pg_temp.zz_check('payments: the new HDFC row records its QR', v_n::int, 1);

  v_fails := current_setting('zz.fails', true);
  RAISE EXCEPTION 'PROBE COMPLETE — % checks, % failed. Nothing was written; this rollback is deliberate.%',
    current_setting('zz.checks', true),
    CASE WHEN v_fails = '' THEN 0 ELSE array_length(string_to_array(ltrim(v_fails, ' |'), ' | '), 1) END,
    CASE WHEN v_fails = '' THEN '' ELSE E'\nFAILURES' || v_fails END;
END
$probe$;
